1	/**
2	 * Environment matrix generator.
3	 *
4	 * Given a configuration describing OS options, language versions and feature
5	 * flags, this module produces a build matrix suitable for a GitHub Actions
6	 * `strategy.matrix`. It supports include/exclude rules, `max-parallel` limits,
7	 * `fail-fast` configuration and validation of a maximum matrix size.
8	 */
9	
10	/** A single concrete combination in the matrix (one job). */
11	export type MatrixCombination = Record<string, string | number | boolean>;
12	
13	/** Thrown when the generated matrix exceeds the configured `maxSize`. */
14	export class MatrixSizeError extends Error {
15	  constructor(
16	    readonly actual: number,
17	    readonly maximum: number,
18	  ) {
19	    super(
20	      `Generated matrix has ${actual} combinations, which exceeds the ` +
21	        `maximum allowed size of ${maximum}.`,
22	    );
23	    this.name = "MatrixSizeError";
24	  }
25	}
26	
27	/** Thrown when the input configuration is invalid. */
28	export class MatrixConfigError extends Error {
29	  constructor(message: string) {
30	    super(message);
31	    this.name = "MatrixConfigError";
32	  }
33	}
34	
35	/** Input configuration describing the dimensions and rules of the matrix. */
36	export interface MatrixConfig {
37	  /** Operating systems to build on (e.g. "ubuntu-latest"). */
38	  os: string[];
39	  /** Language/runtime versions (e.g. "18", "20"). */
40	  language: string[];
41	  /** Optional feature flags; each becomes a `feature` axis value. */
42	  features?: string[];
43	  /** Extra combinations / keys to add (GitHub Actions `include` semantics). */
44	  include?: MatrixCombination[];
45	  /** Combinations to remove (GitHub Actions `exclude` semantics). */
46	  exclude?: MatrixCombination[];
47	  /** Maximum number of jobs run concurrently. */
48	  maxParallel?: number;
49	  /** Whether to cancel in-progress jobs when one fails. */
50	  failFast?: boolean;
51	  /** Hard cap on the number of generated combinations. */
52	  maxSize?: number;
53	}
54	
55	/** The `strategy` object emitted for consumption by GitHub Actions. */
56	export interface StrategyOutput {
57	  matrix: {
58	    include: MatrixCombination[];
59	  };
60	  "max-parallel"?: number;
61	  "fail-fast"?: boolean;
62	}
63	
64	/**
65	 * Build the cartesian product of the named axes. Each axis with at least one
66	 * value multiplies the number of combinations; empty/absent axes are skipped.
67	 */
68	function cartesianProduct(
69	  axes: Array<{ key: string; values: Array<string | number | boolean> }>,
70	): MatrixCombination[] {
71	  // Seed with a single empty combination, then fold each axis over the result.
72	  let combos: MatrixCombination[] = [{}];
73	  for (const axis of axes) {
74	    if (axis.values.length === 0) continue;
75	    const next: MatrixCombination[] = [];
76	    for (const combo of combos) {
77	      for (const value of axis.values) {
78	        next.push({ ...combo, [axis.key]: value });
79	      }
80	    }
81	    combos = next;
82	  }
83	  return combos;
84	}
85	
86	/** The axis keys that participate in the cartesian product. */
87	const AXIS_KEYS = ["os", "language", "feature"] as const;
88	
89	/**
90	 * Does `entry` match `combo`? A match means every key present in `entry` is also
91	 * present in `combo` with an equal value (partial / subset matching, exactly how
92	 * GitHub Actions evaluates `exclude` entries).
93	 */
94	function matches(combo: MatrixCombination, entry: MatrixCombination): boolean {
95	  return Object.entries(entry).every(([key, value]) => combo[key] === value);
96	}
97	
98	/**
99	 * Apply `include` entries using GitHub Actions semantics:
100	 *  - An include is merged into every existing combination whose *axis* values it
101	 *    agrees with (keys not present in the include, or non-axis keys, never block
102	 *    a match).
103	 *  - If an include matches no combination, it is appended as a brand-new one.
104	 */
105	function applyIncludes(
106	  combos: MatrixCombination[],
107	  includes: MatrixCombination[],
108	): MatrixCombination[] {
109	  const result = combos.map((c) => ({ ...c }));
110	  for (const inc of includes) {
111	    // Only the axis keys of the include can disqualify a combination.
112	    const axisConstraints = Object.entries(inc).filter(([k]) =>
113	      (AXIS_KEYS as readonly string[]).includes(k),
114	    );
115	    let matched = false;
116	    for (const combo of result) {
117	      const agrees = axisConstraints.every(([k, v]) => combo[k] === v);
118	      if (agrees) {
119	        Object.assign(combo, inc);
120	        matched = true;
121	      }
122	    }
123	    if (!matched) result.push({ ...inc });
124	  }
125	  return result;
126	}
127	
128	/** Validate the input configuration, throwing MatrixConfigError on problems. */
129	function validateConfig(config: MatrixConfig): void {
130	  if (!Array.isArray(config.os) || config.os.length === 0) {
131	    throw new MatrixConfigError("`os` must be a non-empty array of OS names.");
132	  }
133	  if (!Array.isArray(config.language) || config.language.length === 0) {
134	    throw new MatrixConfigError(
135	      "`language` must be a non-empty array of language versions.",
136	    );
137	  }
138	  if (
139	    config.maxParallel !== undefined &&
140	    (!Number.isInteger(config.maxParallel) || config.maxParallel < 1)
141	  ) {
142	    throw new MatrixConfigError("`maxParallel` must be a positive integer.");
143	  }
144	  if (
145	    config.maxSize !== undefined &&
146	    (!Number.isInteger(config.maxSize) || config.maxSize < 1)
147	  ) {
148	    throw new MatrixConfigError("`maxSize` must be a positive integer.");
149	  }
150	}
151	
152	/**
153	 * Generate the full build matrix from a configuration.
154	 */
155	export function generateMatrix(config: MatrixConfig): StrategyOutput {
156	  validateConfig(config);
157	
158	  const axes: Array<{ key: string; values: Array<string | number | boolean> }> = [
159	    { key: "os", values: config.os },
160	    { key: "language", values: config.language },
161	  ];
162	  if (config.features && config.features.length > 0) {
163	    axes.push({ key: "feature", values: config.features });
164	  }
